namespace EnergyDash.Core;

public enum Fuel { Elec, Gas }
public enum RateRegister { Standard, Day, Night }
public enum RateBand { Off, Disp, Peak, Std }

public sealed class Meter { public long Id { get; set; } public Fuel Fuel { get; set; } public string MpanMprn { get; set; } = ""; public string Serial { get; set; } = ""; public bool IsExport { get; set; } public string Unit { get; set; } = "kWh"; }
public sealed class Agreement { public long Id { get; set; } public Fuel Fuel { get; set; } public string TariffCode { get; set; } = ""; public string ProductCode { get; set; } = ""; public DateTime ValidFromUtc { get; set; } public DateTime? ValidToUtc { get; set; } }
public sealed class UnitRate { public long Id { get; set; } public Fuel Fuel { get; set; } public string TariffCode { get; set; } = ""; public RateRegister Register { get; set; } public DateTime ValidFromUtc { get; set; } public DateTime? ValidToUtc { get; set; } public decimal PenceIncVat { get; set; } }
public sealed class StandingCharge { public long Id { get; set; } public Fuel Fuel { get; set; } public string TariffCode { get; set; } = ""; public DateTime ValidFromUtc { get; set; } public DateTime? ValidToUtc { get; set; } public decimal PencePerDayIncVat { get; set; } }
public sealed class Consumption { public Fuel Fuel { get; set; } public DateTime IntervalStartUtc { get; set; } public DateTime IntervalEndUtc { get; set; } public decimal Kwh { get; set; } public decimal RawValue { get; set; } public string RawUnit { get; set; } = "kWh"; public DateTime FetchedUtc { get; set; } }
public sealed class Dispatch { public long Id { get; set; } public DateTime StartUtc { get; set; } public DateTime EndUtc { get; set; } public decimal? DeltaKwh { get; set; } public string Source { get; set; } = "Flex"; public string DeviceId { get; set; } = ""; public bool IsBoost { get; set; } public DateTime FirstSeenUtc { get; set; } public DateTime LastSeenUtc { get; set; } }
public sealed class BatteryInterval { public DateTime IntervalStartUtc { get; set; } public decimal GridImportKwh { get; set; } public decimal GridExportKwh { get; set; } public decimal BattChargeKwh { get; set; } public decimal BattDischargeKwh { get; set; } public decimal HomeKwh { get; set; } public decimal SolarKwh { get; set; } public decimal? SocEndPct { get; set; } }
public sealed class LiveAccumulator { public DateTime SlotStartUtc { get; set; } public decimal ImportWh { get; set; } public int Samples { get; set; } public DateTime UpdatedUtc { get; set; } public bool HasGap { get; set; } }
public sealed class PricedSlot { public Fuel Fuel { get; set; } public DateTime SlotStartUtc { get; set; } public decimal? Kwh { get; set; } public decimal? RatePence { get; set; } public RateBand Band { get; set; } public string RateSource { get; set; } = ""; public decimal? CostPence { get; set; } public string TariffCode { get; set; } = ""; public DateTime PricedUtc { get; set; } }
public sealed class PricedDay { public Fuel Fuel { get; set; } public DateOnly LocalDate { get; set; } public decimal EnergyCostPence { get; set; } public decimal? StandingPence { get; set; } public int SlotCount { get; set; } public int MissingSlots { get; set; } public int UnpricedSlots { get; set; } public string WarningsJson { get; set; } = "[]"; public DateTime PricedUtc { get; set; } }
public sealed class Setting { public string Key { get; set; } = ""; public string ValueJson { get; set; } = "{}"; }
public sealed class Secret { public string Key { get; set; } = ""; public string Protected { get; set; } = ""; public string Hint { get; set; } = ""; public DateTime UpdatedUtc { get; set; } }
public sealed class AlertRule { public long Id { get; set; } public string Kind { get; set; } = ""; public bool Enabled { get; set; } public string ParamsJson { get; set; } = "{}"; }
public sealed class AlertEvent { public long Id { get; set; } public long RuleId { get; set; } public string SubjectKey { get; set; } = ""; public DateTime FiredUtc { get; set; } public decimal Value { get; set; } public decimal Threshold { get; set; } public string DeliveryJson { get; set; } = "{}"; public decimal? ReconciledValue { get; set; } }
public sealed class ReportRun { public long Id { get; set; } public DateOnly WeekStartLocal { get; set; } public DateTime? SentUtc { get; set; } public string Status { get; set; } = "Pending"; public string? Error { get; set; } }
public sealed class SyncLog { public long Id { get; set; } public string Source { get; set; } = ""; public DateTime StartedUtc { get; set; } public DateTime? FinishedUtc { get; set; } public bool Ok { get; set; } public string Detail { get; set; } = ""; }
public sealed class SyncCommand { public long Id { get; set; } public string Kind { get; set; } = "Sync"; public string? Argument { get; set; } public DateTime CreatedUtc { get; set; } public DateTime? ClaimedUtc { get; set; } public DateTime? CompletedUtc { get; set; } public string? Error { get; set; } }
